const fns = [
  { name: 'validate', calls: 1_000_000, selfUs: 0.8 },
  { name: 'renderReport', calls: 1, selfUs: 500_000 },
  { name: 'lookupUser', calls: 200_000, selfUs: 1.5 },
];
const weighed = fns
  .map(f => ({ name: f.name, totalMs: (f.calls * f.selfUs) / 1000 }))
  .sort((a, b) => b.totalMs - a.totalMs);
for (const f of weighed) console.log(`${f.name}: ${f.totalMs.toFixed(1)} ms`);
console.log('hottest -> ' + weighed[0].name);
